import sys


def subtask_brute(n, a):
    # 暴力档：n<=1000，O(n^2) 直接算
    ans = 0
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                ans += 1
    return ans


def subtask_special(n, a):
    # 特殊性质档：元素两两不同 且 只有相邻两元素会逆序（假设）
    cnt = 0
    for i in range(n - 1):
        if a[i] > a[i + 1]:
            cnt += 1
    return cnt


def full_solve(n, a):
    # 正解档：O(n log n) 归并排序数逆序对
    tmp = [0] * n

    def merge(lo, hi):
        if hi - lo <= 1:
            return 0
        mid = (lo + hi) // 2
        res = merge(lo, mid) + merge(mid, hi)
        i, j, k = lo, mid, lo
        while i < mid and j < hi:
            if a[i] <= a[j]:
                tmp[k] = a[i]; i += 1
            else:
                tmp[k] = a[j]; j += 1
                res += mid - i
            k += 1
        while i < mid:
            tmp[k] = a[i]; i += 1; k += 1
        while j < hi:
            tmp[k] = a[j]; j += 1; k += 1
        a[lo:hi] = tmp[lo:hi]
        return res

    return merge(0, n)


def main():
    # 典型部分分程序：读入规模，按档分派
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        # 无输入时自测三档结果一致（小数据验证）
        test_a = [3, 2, 1, 5, 4]
        b1 = subtask_brute(5, test_a[:])
        f1 = full_solve(5, test_a[:])
        print(f"brute={b1} full={f1}")
        assert b1 == f1
        print("OK (self-test)")
        return
    n = data[0]
    a = data[1:]
    special = all(a[i] != a[j] for i in range(n) for j in range(i + 1, n)) and n <= 200
    if n <= 1000 and not special:
        print(subtask_brute(n, a))
    elif special:
        print(subtask_special(n, a))
    else:
        print(full_solve(n, a))


if __name__ == "__main__":
    main()
